  /* ================= Bác sĩ Font: chuyển trực tiếp trong bản vẽ (UI-J02, Pro) ================= */
  var conv0 = SC.fontConvert;
  SC.fontConvert = function(d){
    if (!pro()) return conv0(d);
    var legacy = d.styles.filter(function(s){ return (s.enc === 'TCVN3' || s.enc === 'VNI') && s.count; }), n = legacy.reduce(function(s, x){ return s + x.count; }, 0);
    if (!legacy.length){ TC.toast('Bản vẽ không còn chữ mã cũ.', { type:'info', log:false }); return; }
    var dlg = TC.dialog({ id:'fdconvp', title:'Chuyển chữ sang Unicode', cmd:'FIXFONT', code:'UI-J02', w:560,
      body:'<div class="stack"><p>Chuyển <b>' + TC.n(n) + '</b> đối tượng chữ của ' + legacy.length + ' kiểu chữ mã cũ ngay trong bản vẽ (một bước hoàn tác).</p><div class="tblwrap"><table class="tbl"><thead><tr><th>Kiểu chữ</th><th>Bảng mã</th><th>Font hiện tại</th><th>Đổi sang</th><th class="num">Chữ</th></tr></thead><tbody>' + legacy.map(function(s){ return '<tr><td>' + esc(s.name) + '</td><td><span class="tag warn">' + s.enc + '</span></td><td class="mono">' + esc(s.font) + '</td><td>' + esc(s.enc === 'VNI' ? 'TrionVN-Arial' : 'TrionVN-Times') + '</td><td class="num">' + TC.n(s.count) + '</td></tr>'; }).join('') + '</tbody></table></div>' + H.rad('fdw', 'in', 'Sửa trực tiếp bản vẽ đang mở', true) + H.rad('fdw', 'copy', 'Lưu thành bản sao, giữ tệp gốc', false) + '</div>',
      foot:'<button class="btn ghost" type="button" id="fdp-prev">Xem trước thay đổi</button><span class="grow"></span><button class="btn ghost" type="button" data-x="cancel">Hủy</button><button class="btn primary" type="button" id="fdp-go">Chuyển đổi</button>' });
    $('#fdp-prev', dlg.el).addEventListener('click', function(){ dlg.close(); SC.fontPreview(d); });
    $('#fdp-go', dlg.el).addEventListener('click', function(){ if ($('[name="fdw"]:checked', dlg.el).value === 'copy'){ dlg.close(); return conv0(d); } dlg.close(true);
      ED.run('Chuyển font sang Unicode', function(){ var done = ED.state(function(){ return legacy.map(function(s){ return { n:s.name, enc:s.enc, font:s.font, missing:s.missing, css:s.css, upper:s.upper }; }); }, function(arr){ arr.forEach(function(x){ var s = d.styleMap[x.n]; if (s) Object.assign(s, { enc:x.enc, font:x.font, missing:x.missing, css:x.css, upper:x.upper }); }); A().refreshPalettes(); A().renderStatus(); V().draw(); }); legacy.forEach(function(s){ s.font = s.enc === 'VNI' ? 'TrionVN-Arial.shx' : 'TrionVN-Times.shx'; s.enc = 'Unicode'; s.missing = false; s.upper = false; }); done(); });
      A().unbanner(d, 'fontdoc'); A().refreshPalettes(); A().renderStatus(); V().draw();
      TC.toast('Đã chuyển ' + TC.n(n) + ' đối tượng chữ sang Unicode. Bản vẽ mở đúng trên mọi máy.', { kind:'task', act:{ label:'Hoàn tác', fn:function(){ ED.undo(1); } } }); });
  };
